import React from "react";

function Home() {
  return (
    <div className="glass-card">
      <h1>Welcome to Hire Professional</h1>
      <p>Find and hire the right professional for your needs with ease!</p>
      <img 
        src="https://cdn-icons-png.flaticon.com/512/4144/4144483.png"
        alt="cloud"
        style={{ width: "120px", marginTop: "20px" }}
      />
    </div>
  );
}

export default Home;
